const html = "<!doctype html>\n<html lang=\"ru\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Культурный интеллект - коммерческое предложение</title>\n    <meta\n      name=\"description\"\n      content=\"Три формата программы по культурному интеллекту: игра, 5-часовой тренинг и полный день практики с сертификатом.\"\n    />\n    <style>:root {\n  color-scheme: light;\n  --ink: #111d30;\n  --muted: #596578;\n  --line: #c4d3f1;\n  --paper: #f4f8ff;\n  --soft: #eaf1fb;\n  --blue: #172a62;\n  --blue-deep: #081338;\n  --blue-mid: #102154;\n  --blue-soft: #dce7fb;\n  --green: #078665;\n  --red: #c8443e;\n  --yellow: #d6a316;\n  --accent: var(--blue);\n  --accent-strong: #0c1741;\n  --gold: var(--yellow);\n  --coral: var(--red);\n  --white: #ffffff;\n  --shadow: 0 24px 70px rgba(3, 8, 25, 0.24);\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  margin: 0;\n  font-family: Manrope, Inter, \"Segoe UI\", Arial, sans-serif;\n  color: var(--white);\n  background: var(--blue);\n}\n\na {\n  color: inherit;\n  text-decoration: none;\n}\n\n.hero {\n  position: relative;\n  min-height: 84vh;\n  display: grid;\n  align-items: center;\n  overflow: hidden;\n  padding: 88px clamp(20px, 6vw, 78px) 56px;\n  color: var(--white);\n}\n\n.hero-image,\n.hero-overlay {\n  position: absolute;\n  inset: 0;\n}\n\n.hero-image {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.hero-overlay {\n  background:\n    linear-gradient(90deg, rgba(0, 0, 0, 0.88), rgba(0, 0, 0, 0.58) 42%, rgba(0, 0, 0, 0.12)),\n    linear-gradient(0deg, rgba(0, 0, 0, 0.58), rgba(0, 0, 0, 0.06) 34%);\n}\n\n.hero-content {\n  position: relative;\n  z-index: 1;\n  width: min(780px, 100%);\n}\n\n.eyebrow {\n  margin: 0 0 14px;\n  color: var(--gold);\n  font-size: 13px;\n  font-weight: 800;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n}\n\nh1,\nh2,\nh3,\np {\n  overflow-wrap: anywhere;\n}\n\nh1 {\n  margin: 0;\n  max-width: 760px;\n  font-size: clamp(42px, 7.4vw, 86px);\n  line-height: 0.97;\n  letter-spacing: 0;\n}\n\n.lead {\n  max-width: 680px;\n  margin: 24px 0 0;\n  color: rgba(255, 255, 255, 0.88);\n  font-size: clamp(18px, 2.1vw, 23px);\n  line-height: 1.45;\n}\n\n.hero-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  margin-top: 34px;\n}\n\n.button {\n  display: inline-flex;\n  min-height: 48px;\n  align-items: center;\n  justify-content: center;\n  border: 1px solid transparent;\n  border-radius: 6px;\n  padding: 13px 20px;\n  font-weight: 800;\n  line-height: 1.2;\n  cursor: pointer;\n  transition: transform 180ms ease, background 180ms ease, border-color 180ms ease;\n}\n\n.button:hover {\n  transform: translateY(-2px);\n}\n\n.primary {\n  color: var(--white);\n  background: var(--blue);\n}\n\n.primary:hover {\n  background: var(--accent-strong);\n}\n\n.secondary {\n  color: var(--white);\n  border-color: rgba(255, 255, 255, 0.44);\n  background: rgba(255, 255, 255, 0.12);\n}\n\n.section {\n  padding: clamp(56px, 8vw, 104px) clamp(20px, 6vw, 78px);\n}\n\n.intro {\n  position: relative;\n  overflow: hidden;\n  display: grid;\n  grid-template-columns: minmax(260px, 0.9fr) minmax(280px, 1.1fr);\n  gap: clamp(28px, 6vw, 82px);\n  background: var(--blue);\n}\n\n.intro::before {\n  content: \"\";\n  position: absolute;\n  top: -96px;\n  right: clamp(-64px, -2vw, -18px);\n  width: 430px;\n  height: 416px;\n  border: 2px dashed rgba(196, 211, 241, 0.62);\n  border-radius: 50%;\n  opacity: 1;\n  pointer-events: none;\n}\n\n.intro::after {\n  content: \"\";\n  position: absolute;\n  left: clamp(-70px, -3vw, -24px);\n  bottom: -94px;\n  width: 360px;\n  height: 348px;\n  border: 2px dashed rgba(196, 211, 241, 0.34);\n  border-radius: 50%;\n  opacity: 1;\n  pointer-events: none;\n}\n\n.intro > * {\n  position: relative;\n  z-index: 1;\n}\n\nh2 {\n  margin: 0;\n  font-size: clamp(30px, 4vw, 52px);\n  line-height: 1.08;\n  letter-spacing: 0;\n}\n\n.intro-copy p,\n.framework-text p,\n.section-heading p,\n.request-copy p {\n  color: rgba(255, 255, 255, 0.78);\n  font-size: 18px;\n  line-height: 1.66;\n}\n\n.intro-copy p:first-child {\n  margin-top: 0;\n}\n\n.use-cases {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 1px;\n  padding-top: 0;\n  background: var(--blue);\n}\n\n.use-cases article {\n  min-height: 240px;\n  padding: 30px;\n  border: 1px solid var(--line);\n  background: #f8fbff;\n  color: var(--ink);\n}\n\n.use-cases article:nth-child(1) span {\n  color: var(--red);\n}\n\n.use-cases article:nth-child(2) span {\n  color: var(--yellow);\n}\n\n.use-cases article:nth-child(3) span {\n  color: var(--green);\n}\n\n.use-cases span {\n  font-weight: 800;\n}\n\n.use-cases h3,\n.pricing-card h3 {\n  margin: 20px 0 12px;\n  color: var(--ink);\n  font-size: 24px;\n  line-height: 1.16;\n}\n\n.use-cases p,\n.pricing-card p,\n.pricing-card li,\n.steps p {\n  color: var(--muted);\n  line-height: 1.55;\n}\n\n.framework {\n  position: relative;\n  overflow: hidden;\n  display: grid;\n  grid-template-columns: minmax(280px, 0.95fr) minmax(300px, 1.05fr);\n  gap: clamp(32px, 6vw, 78px);\n  align-items: start;\n  margin: clamp(34px, 5vw, 64px) clamp(20px, 6vw, 78px);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background:\n    radial-gradient(circle at 86% 12%, rgba(196, 211, 241, 0.16), transparent 25%),\n    linear-gradient(135deg, var(--blue-mid), var(--blue-deep));\n  box-shadow:\n    inset 0 0 0 1px rgba(255, 255, 255, 0.05),\n    0 24px 70px rgba(3, 8, 25, 0.22);\n}\n\n.framework::before,\n.framework::after {\n  content: \"\";\n  position: absolute;\n  border: 2px dashed rgba(196, 211, 241, 0.4);\n  border-radius: 50%;\n  pointer-events: none;\n}\n\n.framework::before {\n  top: -86px;\n  right: clamp(18px, 6vw, 96px);\n  width: 286px;\n  height: 276px;\n  opacity: 1;\n}\n\n.framework::after {\n  left: clamp(16px, 5vw, 64px);\n  bottom: -58px;\n  width: 206px;\n  height: 198px;\n  opacity: 1;\n}\n\n.framework > * {\n  position: relative;\n  z-index: 1;\n}\n\n.steps {\n  display: grid;\n  gap: 14px;\n}\n\n.steps div {\n  color: var(--ink);\n  border: 1px solid var(--line);\n  border-left: 5px solid var(--red);\n  padding: 22px 24px;\n  background: #f8fbff;\n  box-shadow: 0 18px 44px rgba(3, 8, 25, 0.18);\n}\n\n.steps div:nth-child(2) {\n  border-left-color: var(--yellow);\n}\n\n.steps div:nth-child(3) {\n  border-left-color: var(--green);\n}\n\n.steps strong {\n  display: block;\n  color: var(--ink);\n  font-size: 22px;\n}\n\n.formats {\n  position: relative;\n  overflow: hidden;\n  background:\n    radial-gradient(circle at 84% 12%, rgba(0, 155, 219, 0.22), transparent 26%),\n    var(--blue);\n}\n\n.formats::before {\n  content: \"\";\n  position: absolute;\n  top: 28px;\n  right: clamp(12px, 5vw, 74px);\n  width: 276px;\n  height: 266px;\n  border: 2px dashed rgba(196, 211, 241, 0.58);\n  border-radius: 50%;\n  opacity: 1;\n}\n\n.formats::after {\n  content: \"\";\n  position: absolute;\n  left: clamp(20px, 4vw, 58px);\n  bottom: 28px;\n  width: 190px;\n  height: 184px;\n  border: 2px dashed rgba(196, 211, 241, 0.34);\n  border-radius: 50%;\n  opacity: 1;\n}\n\n.formats > * {\n  position: relative;\n  z-index: 1;\n}\n\n.section-heading {\n  max-width: 760px;\n  margin-bottom: 34px;\n}\n\n.pricing-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 18px;\n  align-items: stretch;\n}\n\n.pricing-card {\n  --plan-color: var(--blue);\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-height: 610px;\n  padding: 26px;\n  overflow: hidden;\n  color: var(--ink);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f8fbff;\n  transition:\n    transform 180ms ease,\n    border-color 180ms ease,\n    box-shadow 180ms ease;\n}\n\n.pricing-card:nth-child(1) {\n  --plan-color: var(--red);\n}\n\n.pricing-card:nth-child(2) {\n  --plan-color: var(--green);\n}\n\n.pricing-card:nth-child(3) {\n  --plan-color: var(--yellow);\n}\n\n.pricing-card::before {\n  content: \"\";\n  position: absolute;\n  top: 14px;\n  right: 14px;\n  width: 104px;\n  height: 100px;\n  border: 2px dashed color-mix(in srgb, var(--plan-color) 52%, transparent);\n  border-radius: 50%;\n  opacity: 0;\n  transform: scale(0.88);\n  transition: opacity 180ms ease, transform 180ms ease;\n  pointer-events: none;\n}\n\n.pricing-card:hover,\n.pricing-card:focus-within {\n  transform: translateY(-6px);\n  border-color: var(--plan-color);\n  box-shadow: var(--shadow);\n}\n\n.pricing-card:hover::before,\n.pricing-card:focus-within::before {\n  opacity: 1;\n  transform: scale(1);\n}\n\n.tag {\n  display: inline-flex;\n  width: fit-content;\n  margin: 0;\n  border-radius: 999px;\n  padding: 7px 12px;\n  color: var(--plan-color);\n  background: color-mix(in srgb, var(--plan-color) 13%, white);\n  font-size: 13px;\n  font-weight: 800;\n  transition: color 180ms ease, background 180ms ease;\n}\n\n.pricing-card:hover .tag,\n.pricing-card:focus-within .tag {\n  color: var(--white);\n  background: var(--plan-color);\n}\n\n.pricing-card ul {\n  display: grid;\n  gap: 11px;\n  margin: 24px 0;\n  padding-left: 20px;\n}\n\n.price {\n  margin-top: auto;\n  padding-top: 12px;\n}\n\n.price strong {\n  display: block;\n  font-size: 34px;\n  line-height: 1;\n}\n\n.price span {\n  display: block;\n  margin-top: 7px;\n  color: var(--muted);\n}\n\n.card-button {\n  width: 100%;\n  margin-top: 22px;\n  color: var(--plan-color);\n  border-color: var(--plan-color);\n  background: transparent;\n}\n\n.card-button:hover {\n  color: var(--white);\n  background: var(--plan-color);\n}\n\n.request-section {\n  position: relative;\n  overflow: hidden;\n  display: grid;\n  grid-template-columns: minmax(280px, 0.85fr) minmax(320px, 1.15fr);\n  gap: clamp(30px, 6vw, 82px);\n  background: var(--blue);\n}\n\n.request-section::before,\n.request-section::after {\n  content: \"\";\n  position: absolute;\n  border: 2px dashed rgba(196, 211, 241, 0.38);\n  border-radius: 50%;\n  pointer-events: none;\n}\n\n.request-section::before {\n  top: -72px;\n  left: clamp(-76px, -3vw, -26px);\n  width: 376px;\n  height: 364px;\n  opacity: 1;\n}\n\n.request-section::after {\n  right: clamp(18px, 6vw, 80px);\n  bottom: 12px;\n  width: 264px;\n  height: 254px;\n  opacity: 1;\n}\n\n.request-section > * {\n  position: relative;\n  z-index: 1;\n}\n\n.request-form {\n  display: grid;\n  gap: 16px;\n  padding: 28px;\n  color: var(--ink);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  background: #f8fbff;\n}\n\nlabel {\n  display: grid;\n  gap: 8px;\n  color: var(--ink);\n  font-weight: 800;\n}\n\ninput,\nselect,\ntextarea {\n  width: 100%;\n  border: 1px solid var(--line);\n  border-radius: 6px;\n  padding: 14px 15px;\n  color: var(--ink);\n  background: var(--white);\n  font: inherit;\n}\n\ntextarea {\n  resize: vertical;\n}\n\ninput:focus,\nselect:focus,\ntextarea:focus {\n  outline: 3px solid rgba(23, 42, 98, 0.16);\n  border-color: var(--blue);\n}\n\n.submit-button {\n  width: 100%;\n  margin-top: 4px;\n  border: 0;\n}\n\n.form-note {\n  min-height: 24px;\n  margin: 0;\n  color: var(--blue);\n  font-weight: 700;\n}\n\n.footer {\n  display: flex;\n  justify-content: space-between;\n  gap: 18px;\n  padding: 28px clamp(20px, 6vw, 78px);\n  color: rgba(255, 255, 255, 0.75);\n  background: var(--blue-deep);\n}\n\n.footer p {\n  margin: 0;\n}\n\n.footer a {\n  font-weight: 800;\n}\n\n@media (max-width: 920px) {\n  .intro,\n  .framework,\n  .pricing-grid,\n  .request-section {\n    grid-template-columns: 1fr;\n  }\n\n  .pricing-card {\n    min-height: auto;\n  }\n\n  .use-cases {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 640px) {\n  .framework {\n    margin: 24px 20px;\n    padding: 38px 22px;\n  }\n\n  .hero {\n    min-height: 78vh;\n    padding-top: 64px;\n  }\n\n  h1 {\n    font-size: 38px;\n  }\n\n  .hero-actions,\n  .button {\n    width: 100%;\n  }\n\n  .footer {\n    flex-direction: column;\n  }\n}\n</style>\n  </head>\n  <body>\n    <main id=\"top\">\n      <section class=\"hero\">\n        <img\n          class=\"hero-image\"\n          src=\"data:image/jpeg;base64,\"\n          alt=\"Игровое поле и карточки тренинга по культурному интеллекту\"\n        />\n        <div class=\"hero-overlay\"></div>\n        <div class=\"hero-content\">\n          <h1>Культурный интеллект для эффективных коммуникаций</h1>\n          <p class=\"lead\">\n            Практические форматы для команд, которым важно лучше понимать разные установки,\n            улучшать коммуникации и договариваться быстрее.\n          </p>\n          <div class=\"hero-actions\">\n            <a class=\"button primary\" href=\"#formats\">Выбрать формат</a>\n            <a class=\"button secondary\" href=\"#request\">Оставить заявку</a>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"section intro\" aria-labelledby=\"intro-title\">\n        <div>\n          <p class=\"eyebrow\">Зачем это команде</p>\n          <h2 id=\"intro-title\">Культура влияет не только на страны, но и на работу</h2>\n        </div>\n        <div class=\"intro-copy\">\n          <p>\n            Культура - это то, как “принято вести дела”: набор убеждений о правильном\n            поведении, решениях, времени, правилах, иерархии, отношениях и результате.\n          </p>\n          <p>\n            Культурный интеллект помогает распознавать эти установки у себя и других,\n            подстраиваться без потери позиции и корректировать коммуникацию там, где\n            различия мешают договориться.\n          </p>\n        </div>\n      </section>\n\n      <section class=\"section use-cases\" aria-label=\"Где пригодится культурный интеллект\">\n        <article>\n          <span>01</span>\n          <h3>Переговоры и продажи</h3>\n          <p>Лучше понимать ожидания клиента, стиль принятия решений и границы доверия.</p>\n        </article>\n        <article>\n          <span>02</span>\n          <h3>Команды и управление</h3>\n          <p>Уменьшать недопонимание между поколениями, функциями, ролями и уровнями иерархии.</p>\n        </article>\n        <article>\n          <span>03</span>\n          <h3>Конфликты и изменения</h3>\n          <p>Видеть, где спор идет не о фактах, а о разных представлениях о “правильно”.</p>\n        </article>\n      </section>\n\n      <section class=\"section framework\" id=\"program\" aria-labelledby=\"program-title\">\n        <div class=\"framework-text\">\n          <p class=\"eyebrow\">Что внутри</p>\n          <h2 id=\"program-title\">Участники проходят путь от осознания к действию</h2>\n          <p>\n            Программа работает с четырьмя уровнями культурного интеллекта: знаниями о различиях,\n            осознанием динамики во взаимодействии, мотивацией к новому опыту и\n            поведенческой уместностью в коммуникации.\n          </p>\n        </div>\n        <div class=\"steps\" aria-label=\"Три шага развития CQ\">\n          <div>\n            <strong>Распознай</strong>\n            <p>Увидеть культурные установки: свои, командные и чужие.</p>\n          </div>\n          <div>\n            <strong>Подстройся</strong>\n            <p>Найти способ взаимодействовать без обесценивания другой позиции.</p>\n          </div>\n          <div>\n            <strong>Скорректируй</strong>\n            <p>Выбрать поведение, которое помогает задаче, отношениям и результату.</p>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"section formats\" id=\"formats\" aria-labelledby=\"formats-title\">\n        <div class=\"section-heading\">\n          <p class=\"eyebrow\">Три варианта на выбор</p>\n          <h2 id=\"formats-title\">Форматы программы</h2>\n          <p>Все варианты рассчитаны на группу от 6 до 10 человек и адаптируются под контекст команды.</p>\n        </div>\n\n        <div class=\"pricing-grid\">\n          <article class=\"pricing-card\" data-plan=\"Игра\">\n            <div class=\"card-top\">\n              <p class=\"tag\">2-2.5 часа</p>\n              <h3>Игра “Культурный интеллект”</h3>\n              <p>\n                Интерактивное знакомство с тем, что у людей могут быть разные культурные\n                установки и разные способы действовать в одной ситуации.\n              </p>\n            </div>\n            <ul>\n              <li>Разбор понятия культуры в широком смысле</li>\n              <li>Практика распознавания различий через игровые ситуации</li>\n              <li>Обсуждение, как различия помогают или мешают команде</li>\n              <li>Группа от 6 до 10 человек</li>\n            </ul>\n            <div class=\"price\"><strong>3 000 ₽</strong><span>с человека</span></div>\n            <a class=\"button card-button\" href=\"#request\">Выбрать игру</a>\n          </article>\n\n          <article class=\"pricing-card\" data-plan=\"Тренинг\">\n            <div class=\"card-top\">\n              <p class=\"tag\">5 часов</p>\n              <h3>Тренинг “Културный интеллект: уровни и установки”</h3>\n              <p>\n                Полноценный тренинг по уровням культурного интеллекта: от знаний о различиях\n                до поведенческой уместности в сложных коммуникациях.\n              </p>\n            </div>\n            <ul>\n              <li>Все уровни культурного интеллекта: когнитивный, метакогнитивный, мотивационный, поведенческий</li>\n              <li>Самодиагностика собственных культурных установок</li>\n              <li>Практика понимания установок других людей</li>\n              <li>Группа от 6 до 10 человек</li>\n            </ul>\n            <div class=\"price\"><strong>5 000 ₽</strong><span>с человека</span></div>\n            <a class=\"button card-button\" href=\"#request\">Выбрать тренинг</a>\n          </article>\n\n          <article class=\"pricing-card\" data-plan=\"Полный день\">\n            <div class=\"card-top\">\n              <p class=\"tag\">8 часов</p>\n              <h3>Полный день с сертификатом</h3>\n              <p>\n                Расширенная версия тренинга: больше практики, больше кейсов,\n                больше закрепления навыков и сертификат о прохождении.\n              </p>\n            </div>\n            <ul>\n              <li>Глубокая работа с установками и командными кейсами</li>\n              <li>Ролевые упражнения, обратная связь и перенос в рабочие ситуации</li>\n              <li>Сертификат о прохождении программы</li>\n              <li>Группа от 6 до 10 человек</li>\n            </ul>\n            <div class=\"price\"><strong>10 000 ₽</strong><span>с человека</span></div>\n            <a class=\"button card-button\" href=\"#request\">Выбрать полный день</a>\n          </article>\n        </div>\n      </section>\n\n      <section class=\"section request-section\" id=\"request\" aria-labelledby=\"request-title\">\n        <div class=\"request-copy\">\n          <p class=\"eyebrow\">Запись</p>\n          <h2 id=\"request-title\">Оставьте заявку на подходящий формат</h2>\n          <p>\n            После отправки форма откроет письмо с выбранным вариантом. Можно добавить даты,\n            город, формат проведения и любые важные детали про команду. Все форматы\n            проводятся для группы от 6 до 10 человек.\n          </p>\n        </div>\n        <form class=\"request-form\" id=\"request-form\">\n          <label>\n            Имя\n            <input name=\"name\" type=\"text\" placeholder=\"Как к вам обращаться\" required />\n          </label>\n          <label>\n            Контакт\n            <input name=\"contact\" type=\"text\" placeholder=\"Телефон, email или Telegram\" required />\n          </label>\n          <label>\n            Формат\n            <select name=\"plan\" required>\n              <option value=\"Игра\">Игра</option>\n              <option value=\"Тренинг\">Тренинг</option>\n              <option value=\"Полный день\">Полный день</option>\n            </select>\n          </label>\n          <label>\n            Комментарий\n            <textarea\n              name=\"message\"\n              rows=\"4\"\n              placeholder=\"Например: команда продаж, 8 человек, нужен очный формат\"\n            ></textarea>\n          </label>\n          <button class=\"button primary submit-button\" type=\"submit\">Отправить заявку</button>\n          <p class=\"form-note\" id=\"form-note\" role=\"status\"></p>\n        </form>\n      </section>\n    </main>\n\n    <footer class=\"footer\">\n      <p>Культурный интеллект - фокус на эффективные коммуникации</p>\n      <a href=\"#top\">Наверх</a>\n    </footer>\n\n    <script>const form = document.querySelector(\"#request-form\");\nconst planSelect = form.querySelector(\"select[name='plan']\");\nconst note = document.querySelector(\"#form-note\");\n\ndocument.querySelectorAll(\"[data-plan] .card-button\").forEach((button) => {\n  button.addEventListener(\"click\", (event) => {\n    const card = event.currentTarget.closest(\"[data-plan]\");\n    planSelect.value = card.dataset.plan;\n  });\n});\n\nform.addEventListener(\"submit\", (event) => {\n  event.preventDefault();\n\n  const data = new FormData(form);\n  const subject = `Заявка на программу: ${data.get(\"plan\")}`;\n  const body = [\n    `Имя: ${data.get(\"name\")}`,\n    `Контакт: ${data.get(\"contact\")}`,\n    `Формат: ${data.get(\"plan\")}`,\n    \"Группа: от 6 до 10 человек\",\n    `Комментарий: ${data.get(\"message\") || \"Не указан\"}`,\n  ].join(\"\\n\");\n\n  note.textContent = \"Открываю письмо с заполненной заявкой.\";\n  window.location.href = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;\n});\n</script>\n  </body>\n</html>\n";

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }

    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=utf-8",
        "cache-control": "public, max-age=300"
      }
    });
  }
};
